NEW=r'''
{id:"kahf",e:"🏔️",ti:["গুহার যুবকেরা","The Youths of the Cave"],g:"linear-gradient(160deg,#b9a7ff,#2b1f5c)",ref:[18,10,12],pg:[["🌙","কয়েকজন যুবক আল্লাহর ওপর ঈমান এনেছিল। কিন্তু তাদের জাতি তাদের কথা মানল না।"],["⛰️","তারা ঈমান বাঁচাতে একটি গুহায় আশ্রয় নিল।"],["🤲","তারা দোয়া করল, ‘হে আমাদের রব, আপনার কাছ থেকে আমাদের রহমত দিন, আর আমাদের কাজ সহজ করে দিন।’"],["😴✨","আল্লাহ তাদের গুহায় অনেক বছর ঘুমিয়ে রাখলেন। পরে তিনি তাদের জাগিয়ে তুললেন।"]],ls:"ঈমান বাঁচাতে আল্লাহর কাছে দোয়া করতে হয়। তিনি রহমত দিয়ে সাহায্য করেন।"},
{id:"musa",e:"🧺",ti:["ছোট্ট মূসা (আ.)","Baby Musa"],g:"linear-gradient(160deg,#8fe3d0,#1b5a6b)",ref:[28,7,13],pg:[["👶","মূসা (আ.) যখন ছোট্ট শিশু, তখন আল্লাহ তাঁর মায়ের মনে একটি কথা জানিয়ে দিলেন।"],["🌊🧺","আল্লাহ বললেন, ‘ভয় পেয়ো না, দুঃখ করো না। আমি তাকে তোমার কাছেই ফিরিয়ে দেব।’"],["👧🏰","মূসার বোন দূর থেকে সব দেখছিল। শিশুটি ফেরাউনের ঘরে পৌঁছাল।"],["🤱💛","আল্লাহর কথা সত্য হলো। মূসা (আ.) আবার তাঁর মায়ের কোলে ফিরে এলেন।"]],ls:"আল্লাহর ওয়াদা সবসময় সত্য। কঠিন সময়েও ভরসা রাখতে হয়।"},
{id:"yusuf",e:"🌟",ti:["ইউসুফ (আ.)-এর স্বপ্ন","Yusuf's Dream"],g:"linear-gradient(160deg,#ffd86b,#3b2a7a)",ref:[12,4,5],pg:[["🌙⭐","ছোট্ট ইউসুফ (আ.) একদিন এক সুন্দর স্বপ্ন দেখলেন। এগারোটি তারা, সূর্য আর চাঁদ তাঁকে সিজদা করছে।"],["👨‍👦","তিনি বাবা ইয়াকুব (আ.)-কে স্বপ্নটা বললেন। বাবা ভালোবেসে বললেন, ‘এটা ভাইদের বোলো না।’"],["🕳️","পরে ভাইয়েরা হিংসা করে তাঁকে কুয়ায় ফেলে দিল।"],["🤲✨","ইউসুফ (আ.) ধৈর্য ধরলেন। আল্লাহ তাঁকে রক্ষা করলেন এবং অনেক সম্মান দিলেন।"]],ls:"হিংসা করা ভালো না। ধৈর্য ধরলে আল্লাহ সুন্দর পরিণতি দেন।"},
{id:"dawud",e:"🪨",ti:["দাউদ (আ.) ও জালুত","Dawud and Jalut"],g:"linear-gradient(160deg,#ffb27a,#7a2b3a)",ref:[2,250,251],pg:[["⚔️","একদিন মুমিনদের সামনে এক বিশাল শক্তিশালী বাহিনী এল। তাদের নেতা ছিল জালুত।"],["🤲","মুমিনরা ভয় পেল না। তারা দোয়া করল, ‘হে রব, আমাদের ধৈর্য দিন আর আমাদের অটল রাখুন।’"],["🧑‍🦱","দাউদ (আ.) তখন যুবক। আল্লাহর সাহায্যে তিনি জালুতকে পরাজিত করলেন।"],["👑","পরে আল্লাহ তাঁকে রাজ্য আর হিকমত দান করলেন।"]],ls:"শক্তি বড় কথা নয়। আল্লাহর সাহায্যই আসল।"},
{id:"ayyub",e:"🌿",ti:["আইয়ুব (আ.)-এর ধৈর্য","Ayyub's Patience"],g:"linear-gradient(160deg,#a8e6a1,#27604a)",ref:[21,83,84],pg:[["🏡","নবী আইয়ুব (আ.)-এর ওপর কঠিন কষ্ট নেমে এল।"],["🕊️","তবু তিনি অভিযোগ করেননি। তিনি ধৈর্য ধরলেন।"],["🤲","তিনি আল্লাহকে ডেকে বললেন, ‘আমাকে কষ্ট ছুঁয়েছে, আর আপনি সবচেয়ে বড় দয়ালু।’"],["🌈💚","আল্লাহ তাঁর ডাক শুনলেন। তিনি তাঁর কষ্ট দূর করলেন আর রহমত দিলেন।"]],ls:"কষ্টের সময় ধৈর্য ধরে আল্লাহকে ডাকলে তিনি রহমত দেন।"}'''
body=OLD.group(1).rstrip()
s=s[:OLD.start()]+"const STORIES=["+body+","+NEW+"];\nvar ST="+s[OLD.end():]
CSS='''.sbox::after{content:"";position:absolute;inset:-50%;background:conic-gradient(from 0deg,transparent,rgba(255,255,255,.22),transparent 25%,transparent 50%,rgba(255,255,255,.16),transparent 75%);animation:spin 18s linear infinite}
.kcov{box-shadow:0 16px 36px -16px rgba(0,0,0,.55);border-radius:30px;min-height:190px}.kcov span{filter:drop-shadow(0 6px 10px rgba(0,0,0,.35))}
.semo{z-index:1;filter:drop-shadow(0 10px 14px rgba(0,0,0,.35))}.stxt{font-size:1.45rem}
'''
s=s.replace("</style>",CSS+"</style>",1)
open(p,"w",encoding="utf-8").write(s);print("done: 10 stories")
